        c.reason = "Internal child of outlinedTextGroup; classified as glyph/text part and suppressed from production planning.";
        c.properties.originalType = raw.type;
        c.properties.textGroupId = context.outlinedTextGroupId || "pending";
        c.suppressFromPlanner = true;
        c.suppressionReason = "Child of outlined text group; parent text group is the production feature.";
        c.isProductionFeature = false;
        c.effectiveProductionFeature = false;
