        bounds: AMP_cloneBounds(bounds),
        widthPt: width,
        heightPt: height,
        areaPt2: Math.abs(width * height),
        children: [],
        childCount: 0,
        descendantCount: 0,
        suppressedDescendantCount: sourceCount,
        productionDescendantCount: sourceCount,
        effectiveDescendantCount: 0,
        internalDescendantCount: 0,
        isProductionFeature: true,
        effectiveProductionFeature: true,
        suppressFromPlanner: false,
        syntheticFeature: true,
        alpha9xCompositeFeature: true,
        alpha9xCompositeContent: true,
        groupRollupApplied: false
