    var score = AMP_gapEngine2ScoreCandidate(fromFeature, toFeature, overlapRatio, valuePt);
    var c = {
        id: id,
        type: type,
        orientation: orientation,
        category: "itemGap",
        fromFeatureId: fromFeature.id,
        toFeatureId: toFeature.id,
        fromFeatureType: fromFeature.type,
        toFeatureType: toFeature.type,
        fromEdge: fromEdge,
        toEdge: toEdge,
        valuePt: valuePt,
        value: AMP_formatLength(job, valuePt),
        label: "GAP " + AMP_formatLength(job, valuePt),
        score: score,
        overlapRatio: overlapRatio,
        renderMode: "report-only-alpha9x",
        renderStatus: "not-rendered-alpha9x-report-only",
        ruleReason: "Gap Engine 2 report-only " + orientation + " item gap candidate."
    };
    if (orientation === "horizontal") {
        c.anchorStartPt = [p1, p3];
        c.anchorEndPt = [p2, p3];
    } else {
        c.anchorStartPt = [p1, p2];
        c.anchorEndPt = [p1, p3];
    }
