        var feature = job.features[i];
        var effective = AMP_isEffectiveProductionFeature(feature);
        if (!effective && !job.settings.showSuppressedInDebug) {
            internalHidden++;
            continue;
        }
        if (job.settings.debugEffectiveOnly && !effective && !job.settings.showSuppressedInDebug) {
            internalHidden++;
            continue;
        }
        AMP_drawFeatureDebugBox(job, layer, feature, effective);
        rendered++;
