function AMP_alpha9xCleanStatusReason(status, reason) {
    var s = String(status || "");
    var r = String(reason || "");
    if (!r) return "";
    if (s && r.indexOf(s + " - ") === 0) return r.substring((s + " - ").length);
    if (r.indexOf("PASS - ") === 0) return r.substring(7);
    if (r.indexOf("FAIL - ") === 0) return r.substring(7);
    if (r.indexOf("WARNING - ") === 0) return r.substring(10);
    return r;
}

