function AMP_textGapObstructionAssertionAlpha9x(job) {
    try {
        if (!job.settings.gapEngine2RenderTextGlyphGaps || (job.settings.gapEngine2TextGapRenderMode || "Off") !== "Render") return "NOT APPLICABLE";
        var rendered = job.statistics.gapEngine2RenderedTextGlyphGapCount || 0;
        if (rendered <= 0) return "NOT APPLICABLE";
        var checks = job.statistics.textGapLabelArtworkObstructionCheckCount || 0;
        if (checks <= 0) return "FAIL - no text-gap obstruction checks ran";
        if ((job.statistics.unresolvedGapLabelCollisionCount || 0) > 0) return "FAIL - unresolved gap label collision";
        return "PASS";
    } catch (e) { return "FAIL - assertion error"; }
}


function AMP_textGapLeaderRouteAssertionAlpha9x(job) {
    var renderedTextGaps = job.statistics && job.statistics.gapEngine2RenderedTextGlyphGapCount ? job.statistics.gapEngine2RenderedTextGlyphGapCount : 0;
    var checks = job.statistics && job.statistics.textGapLeaderRouteCheckCount ? job.statistics.textGapLeaderRouteCheckCount : 0;
    var fails = job.statistics && job.statistics.textGapLeaderRouteFailCount ? job.statistics.textGapLeaderRouteFailCount : 0;
    var suppressed = job.statistics && job.statistics.textGapLeaderRouteSuppressedNoClearRouteCount ? job.statistics.textGapLeaderRouteSuppressedNoClearRouteCount : 0;
    if (!job.settings || job.settings.gapEngine2TextGapRenderMode !== "Render") return "NOT APPLICABLE";
    if (!job.settings.gapEngine2TextGapLeaderRouteAvoidance) return "NOT ACTIVE";
    if (renderedTextGaps <= 0) return "NOT APPLICABLE - no text/glyph gap labels qualified for rendering";
    if (checks <= 0) return "FAIL - text/glyph gap labels rendered but no leader route checks ran";
    if (fails > 0 && suppressed >= fails) return "PASS - no-clear leader route suppressed";
    if (fails > 0) return "FAIL - one or more leader routes cross artwork";
    return "PASS";
}

function AMP_textGapSuppressedNoClearRouteAssertionAlpha9x(job) {
    try {
        if (!job.settings || job.settings.gapEngine2TextGapRenderMode !== "Render") return "NOT APPLICABLE";
        var fails = job.statistics && job.statistics.textGapLeaderRouteFailCount ? job.statistics.textGapLeaderRouteFailCount : 0;
        var suppressed = job.statistics && job.statistics.textGapLeaderRouteSuppressedNoClearRouteCount ? job.statistics.textGapLeaderRouteSuppressedNoClearRouteCount : 0;
        if (fails <= 0) return "NOT NEEDED";
        if (suppressed >= fails) return "PASS";
        return "FAIL - route failed but label was not suppressed";
    } catch (e) { return "FAIL - assertion error"; }
}

function AMP_gapLabelHaloRemovalAssertionAlpha9x(job) {
    try {
        if ((job.statistics.renderedGapCount || 0) <= 0 && (job.statistics.gapsRendered || 0) <= 0) return "NOT APPLICABLE";
        if (job.settings.gapEngine2GapLabelHaloBackground === false) return "PASS";
        return "FAIL - gap label halo setting enabled";
    } catch (e) { return "FAIL - assertion error"; }
}

